/*
 * Service worker: makes the site work offline.
 *
 * Strategy (chosen for a project with no build step, where files are edited
 * and redeployed as-is):
 *
 *   - Everything same-origin is fetched NETWORK-FIRST. Online visitors always
 *     get the freshest files, so a deploy can never be "stuck" behind a cache.
 *     Each successful response is saved, and served when the network is
 *     unavailable or slow.
 *   - Fonts and vendored libraries never change in place, so they are served
 *     cache-first.
 *   - On install, every file listed in precache.json (generated by
 *     `node tools/gen-precache.mjs`) is downloaded, so lessons that have
 *     never been opened also work offline. If that file is missing or stale
 *     the site still works; offline coverage is just limited to visited pages.
 *   - Photographs (content/media/…) are the exception: there can be hundreds
 *     of them, so they are NOT downloaded on install. Each is saved the first
 *     time it is shown and served from the cache from then on, without asking
 *     the network again. That is safe because a picture's address carries a
 *     hash of its content (photo.jpg?v=1a2b3c4d): a replaced picture has a
 *     new address, and its old copy is dropped when the new one is saved.
 *     They live in a cache of their own, which survives updates of the app.
 *     When a lesson opens, the page also fetches the small copy of each of
 *     its pictures (content/media.js), so offline a picture that was never
 *     shown still appears, at lower resolution.
 */

const CACHE = 'lemma-cache-v1';
const MEDIA_CACHE = 'lemma-media-v1';
const NETWORK_TIMEOUT_MS = 4000;
const IMMUTABLE = /\/(assets\/fonts|vendor)\//;
const MEDIA = /\/content\/media\/.+\.(?:jpe?g|png|webp|avif|gif)$/i;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    try {
      const res = await fetch('precache.json', { cache: 'no-store' });
      if (res.ok) {
        const list = await res.json();
        // Pictures are cached when first shown, never up front (the generator leaves them out; this makes sure).
        const files = (Array.isArray(list.files) ? list.files : []).filter((url) => !MEDIA.test(`/${String(url).split('?')[0]}`));
        // Small batches: polite to the network and tolerant of individual failures.
        for (let i = 0; i < files.length; i += 12) {
          await Promise.allSettled(files.slice(i, i + 12).map((url) => cache.add(new Request(url, { cache: 'reload' }))));
        }
      }
    } catch (err) {
      // Offline during install, or no precache list: fine, we cache as we go.
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => (k.startsWith('lemma-cache-') && k !== CACHE) || (k.startsWith('lemma-media-') && k !== MEDIA_CACHE)).map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

function timeout(ms) {
  return new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), ms));
}

async function cacheFirst(request) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(request);
  if (hit) return hit;
  const res = await fetch(request);
  if (res.ok) cache.put(request, res.clone());
  return res;
}

/** Pictures: the cache first and, on a hit, nothing else. */
async function mediaFirst(event) {
  const request = event.request;
  const cache = await caches.open(MEDIA_CACHE);
  const hit = await cache.match(request);
  if (hit) return hit;
  try {
    const res = await fetch(request);
    if (res.ok && res.type === 'basic') {
      const copy = res.clone();
      event.waitUntil((async () => {
        await cache.put(request, copy);
        // an older version of the same picture (same path, another ?v=) is no longer needed
        const url = new URL(request.url);
        for (const key of await cache.keys(url.origin + url.pathname, { ignoreSearch: true })) {
          if (new URL(key.url).search !== url.search) await cache.delete(key);
        }
      })().catch(() => {}));
    }
    return res;
  } catch (err) {
    // Offline, and this picture was never shown: an older version is better than a hole, and so is
    // its small copy (photo.480.jpg), which is fetched for every picture of a lesson when the lesson opens.
    const old = await cache.match(request, { ignoreSearch: true });
    if (old) return old;
    const url = new URL(request.url);
    const small = url.pathname.replace(/(\.\d+)?(\.[a-z]+)$/i, '.480$2');
    const low = small !== url.pathname ? await cache.match(url.origin + small, { ignoreSearch: true }) : null;
    if (low) return low;
    throw err;
  }
}

async function networkFirst(request) {
  const cache = await caches.open(CACHE);
  const network = fetch(request).then((res) => {
    if (res.ok && res.type === 'basic') cache.put(request, res.clone());
    return res;
  });
  try {
    return await Promise.race([network, timeout(NETWORK_TIMEOUT_MS)]);
  } catch (err) {
    const hit = await cache.match(request, { ignoreSearch: true });
    if (hit) {
      network.catch(() => {}); // let a slow request finish and refresh the cache
      return hit;
    }
    if (request.mode === 'navigate') {
      const shell = (await cache.match('./')) || (await cache.match('index.html'));
      if (shell) return shell;
    }
    return network; // nothing cached: wait for the network after all (or fail)
  }
}

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (MEDIA.test(url.pathname)) { event.respondWith(mediaFirst(event)); return; }
  event.respondWith(IMMUTABLE.test(url.pathname) ? cacheFirst(request) : networkFirst(request));
});
